import{_ as t,c as a,o as s,ag as o}from"./chunks/framework.BlG8Ex8O.js";const d=JSON.parse(`{"title":"Stop Supabase From Pausing Your Project (GitHub Actions Guide)","description":"Supabase pauses free projects after 7 days of inactivity. Here's how I stopped losing access to mine — and how you can too, with a free GitHub Action","frontmatter":{"title":"Stop Supabase From Pausing Your Project (GitHub Actions Guide)","date":"2026-09-03T00:00:00.000Z","description":"Supabase pauses free projects after 7 days of inactivity. Here's how I stopped losing access to mine — and how you can too, with a free GitHub Action","image":"","tags":["Software Engineering","Database"]},"headers":[],"relativePath":"posts/stop-supabase-from-pausing-your-project.md","filePath":"posts/stop-supabase-from-pausing-your-project.md"}`),n={name:"posts/stop-supabase-from-pausing-your-project.md"};function r(p,e,i,l,c,u){return s(),a("div",null,[...e[0]||(e[0]=[o(`<p>Supabase is very nice and its generous free plan is my first option when I build a project that needs a relational database. But like every free plan, there are some constraints. I&#39;ll definitely pay for the Pro plan once my project is production-ready and delivering a service that customers pay a subscription for, but during the development phase, I stick with the free plan.</p><h2 id="my-first-hit-to-the-wall-paused-project-for-90-days" tabindex="-1">My first hit to the wall - paused project for 90 days <a class="header-anchor" href="#my-first-hit-to-the-wall-paused-project-for-90-days" aria-label="Permalink to &quot;My first hit to the wall - paused project for 90 days&quot;">​</a></h2><p>I totally understand that in order to keep their resources spent at a minimum for free plan projects, they have to limit how long a project stays active without use. That time is 7 days. So, Supabase Free Tier projects automatically pause after <strong>7 days of inactivity</strong>, and allow direct dashboard restoration for up to <strong>90 days</strong> after pausing.</p><p>I was working on a side project whenever I could find the time. The gap between my commits was never longer than 2-3 weeks, depending on how much free time I had as a full-time employee and father. Every time the project got paused, I knew I had 90 days to restore it. But one day, when I went to resume it, I hit the wall: <strong>&quot;Project can no longer be restored through the dashboard.&quot;</strong> Honestly, I&#39;m not sure how it happened - I was sure I&#39;d touched that project within the 90 days - but it happened anyway. Luckily it wasn&#39;t a production-ready project, so I took it as a chance to learn how to restore one, and I managed it successfully. There were two recovery options, and I went with the first: restore the backup to a new Supabase project. The other option was restoring the backup on your local machine.</p><h2 id="solution-for-keeping-it-alive" tabindex="-1">Solution for keeping it alive <a class="header-anchor" href="#solution-for-keeping-it-alive" aria-label="Permalink to &quot;Solution for keeping it alive&quot;">​</a></h2><p>This can happen again, I thought, so I needed a fix. Recently I was working on a project where I used a daily cron job through Vercel (since that project was hosted there). My intention was to fetch some event data for that particular day, not to keep my Supabase project alive - but that turned out to be a nice side effect.</p><p>The project I&#39;m talking about here was also hosted on Vercel, but I wanted to explore other options too. That&#39;s how I found an even cheaper one: GitHub Actions. Below, I&#39;ll walk you through step by step how you can keep your project alive (but don&#39;t be rude and waste Supabase&#39;s generous offer - if you&#39;re done with a project, just delete it or let it stay paused) for those times you&#39;re tired of resuming a project every time you go quiet on it for more than 7 days (but you know you&#39;ll be back within the next 83, for sure).</p><h2 id="setting-up-a-github-action" tabindex="-1">Setting up a GitHub action <a class="header-anchor" href="#setting-up-a-github-action" aria-label="Permalink to &quot;Setting up a GitHub action&quot;">​</a></h2><h3 id="step-1-get-your-supabase-api-keys" tabindex="-1">Step 1: <strong>Get your Supabase API keys</strong> <a class="header-anchor" href="#step-1-get-your-supabase-api-keys" aria-label="Permalink to &quot;Step 1: **Get your Supabase API keys**&quot;">​</a></h3><p>Go to your Supabase project dashboard → Project Settings (gear icon) → API.</p><p>Copy the &#39;Project URL&#39; (looks like <a href="https://abcdefgh.supabase.co" target="_blank" rel="noreferrer">https://abcdefgh.supabase.co</a>) and the &#39;anon public&#39; key. You&#39;ll need both in a later step.</p><h3 id="step-2-open-your-github-repo" tabindex="-1">Step 2: <strong>Open your GitHub repo</strong> <a class="header-anchor" href="#step-2-open-your-github-repo" aria-label="Permalink to &quot;Step 2: **Open your GitHub repo**&quot;">​</a></h3><p>Go to github.com and open the repository connected to this project. If your Supabase project isn&#39;t already linked to a GitHub repo, just create a new empty repo - this workflow doesn&#39;t need to touch your actual app code.</p><h3 id="step-3-create-the-workflow-folder-structure" tabindex="-1">Step 3: <strong>Create the workflow folder structure</strong> <a class="header-anchor" href="#step-3-create-the-workflow-folder-structure" aria-label="Permalink to &quot;Step 3: **Create the workflow folder structure**&quot;">​</a></h3><p>In your repo, click &#39;Add file&#39; → &#39;Create new file&#39;. In the filename box, type: .github/workflows/keep-alive.yml — GitHub will automatically create the .github and workflows folders for you as you type the slashes.</p><h3 id="step-4-paste-in-the-workflow-code" tabindex="-1">Step 4: <strong>Paste in the workflow code</strong> <a class="header-anchor" href="#step-4-paste-in-the-workflow-code" aria-label="Permalink to &quot;Step 4: **Paste in the workflow code**&quot;">​</a></h3><p>In the file content box, paste:</p><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#85E89D;">name</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">Keep Supabase Alive</span></span>
<span class="line"><span style="color:#79B8FF;">on</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#85E89D;">  schedule</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#E1E4E8;">    - </span><span style="color:#85E89D;">cron</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&#39;0 0 */3 * *&#39;</span></span>
<span class="line"><span style="color:#85E89D;">  workflow_dispatch</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"></span>
<span class="line"><span style="color:#85E89D;">jobs</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#85E89D;">  ping</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#85E89D;">    runs-on</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">ubuntu-latest</span></span>
<span class="line"><span style="color:#85E89D;">    steps</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#E1E4E8;">      - </span><span style="color:#85E89D;">name</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">Ping Supabase</span></span>
<span class="line"><span style="color:#85E89D;">        run</span><span style="color:#E1E4E8;">: </span><span style="color:#F97583;">|</span></span>
<span class="line"><span style="color:#9ECBFF;">          curl -X GET &quot;\${{ secrets.SUPABASE_URL }}/rest/v1/YOUR_TABLE_NAME?select=id&amp;limit=1&quot; \\</span></span>
<span class="line"><span style="color:#9ECBFF;">          -H &quot;apikey: \${{ secrets.SUPABASE_ANON_KEY }}&quot; \\</span></span>
<span class="line"><span style="color:#9ECBFF;">          -H &quot;Authorization: Bearer \${{ secrets.SUPABASE_ANON_KEY }}&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>Replace <code>YOUR_TABLE_NAME</code> with a real table name from your Supabase project. You can find your table names in the Supabase dashboard under <strong>Table Editor</strong></p><p>Then click &#39;Commit changes&#39; at the bottom (commit directly to main is fine).</p><h3 id="step-5-add-your-supabase-keys-as-github-secrets" tabindex="-1">Step 5: <strong>Add your Supabase keys as GitHub secrets</strong> <a class="header-anchor" href="#step-5-add-your-supabase-keys-as-github-secrets" aria-label="Permalink to &quot;Step 5: **Add your Supabase keys as GitHub secrets**&quot;">​</a></h3><p>In your repo, go to Settings (top tab) → Secrets and variables → Actions → &#39;New repository secret&#39;. Add two secrets: name it <code>SUPABASE_URL</code> with value being your Project URL from step 1, then add another named <code>SUPABASE_ANON_KEY</code> with your anon key. Secrets keep these hidden from anyone viewing your repo.</p><h3 id="step-6-test-it-manually" tabindex="-1">Step 6: <strong>Test it manually</strong> <a class="header-anchor" href="#step-6-test-it-manually" aria-label="Permalink to &quot;Step 6: **Test it manually**&quot;">​</a></h3><p>Go to the &#39;Actions&#39; tab at the top of your repo. Click on &#39;Keep Supabase Alive&#39; in the left sidebar, then click the &#39;Run workflow&#39; dropdown button on the right and hit the green &#39;Run workflow&#39; button. This triggers it immediately using the workflow_dispatch trigger, so you don&#39;t have to wait 3 days to see if it works.</p><h3 id="step-7-check-the-run-succeeded" tabindex="-1">Step 7: <strong>Check the run succeeded</strong> <a class="header-anchor" href="#step-7-check-the-run-succeeded" aria-label="Permalink to &quot;Step 7: **Check the run succeeded**&quot;">​</a></h3><p>After ~10-20 seconds, refresh the Actions tab and click into the run. If you see a green checkmark, it worked. Click into the &#39;ping&#39; job and expand the &#39;Ping Supabase&#39; step to see the actual curl response and you should see some JSON back from Supabase, not an error. Mine looks like this:</p><p>!Screenshot 2026-09-03 at 11.21.51.png</p><h2 id="and-that-s-it-let-it-run-automatically-from-here" tabindex="-1">And that’s it - l<strong>et it run automatically from here</strong> <a class="header-anchor" href="#and-that-s-it-let-it-run-automatically-from-here" aria-label="Permalink to &quot;And that’s it - l**et it run automatically from here**&quot;">​</a></h2><p>Problem solved. GitHub will now run this every 3 days on its own schedule (the <code>*/3</code> in the cron line). No further action needed.</p><p>Note: GitHub may skip or delay scheduled runs by a few minutes on the free tier, which is why running every 3 days (instead of exactly 7) gives you a safety buffer.</p><p>Have fun, and keep on creating, unbothered.</p><p>P.S. And don&#39;t forget to buy the Pro plan once you succeed, so someone else can use the free tier too.</p>`,32)])])}const y=t(n,[["render",r]]);export{d as __pageData,y as default};
